      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så det kan ikke vurderes, om en kilde understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en generel betingelse, nemlig behov for yderligere oplysninger eller at en afgørelse ikke kan træffes, uden støtte i materialet. Kilden knytter anmodningen til utilstrækkelig beskrivelse af art og grad i de indsendte lægefaglige oplysninger, i særlige tilfælde."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Kvalifikationen 'i særlige tilfælde' mangler. Det er ikke bevaret, at eksemplerne er illustrative alternativer, og 'stor tvivl' indgår ikke."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: behov for yderligere oplysninger, hvis afgørelse ikke kan træffes på det foreliggende. Der er ingen indbyrdes modsigelse, selvom indholdet er for generelt."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "'Kan' er bevaret, men den snævre mulighed i særlige tilfælde bliver til en bred adgang ved ethvert behov for yderligere oplysninger. Det udvander kildens skønsmæssige og begrænsede karakter."
    }
  },
